import debounce from 'lodash.debounce';

import { getViewNameFromTabId, replaceLayout as commonReplaceLayout } from '@common/utils/layout';
import { currentOFIdentity } from '@common/utils/window';

import { clonePage } from '@common/api/pages';
import { AttachedPageInternal } from '@common/api/pages/shapes';

import { dispatch, getState } from '@enterprise/api/pages/state';
import { selectPageWithIndex, updatePageAtIndex } from '@enterprise/slices/pages/attached';

import { AttachedPage, getCurrentSync, PageLayout } from '@client-platform/index';

export const replaceLayout = async (layout: PageLayout, page: AttachedPage): Promise<void> => {
    // Set layout ready to false so dirty events are not handled while the layout is being replaced.
    const [, index] = selectPageWithIndex(getState(), page.pageId);

    dispatch(updatePageAtIndex({ index, page: { isLayoutReady: false } }));

    return commonReplaceLayout(layout, page);
};

const updatePageToHighLevelViewTab = async (activePage: AttachedPageInternal, viewName: string) => {
    const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
    if (activePage.attachedPageType !== 'singleView') {
        const clonedPage = await clonePage(activePage);
        delete clonedPage.layout;
        delete clonedPage.pageId;
        const view = fin.View.wrapSync({ uuid: currentOFIdentity.uuid, name: viewName });
        const viewInfo = await view.getInfo();
        const newActivePage: AttachedPageInternal = {
            ...clonedPage,
            // Strip the page tab of its title, as the tab will automatically use the view title
            title: null,
            singleViewName: viewName,
            hasUnsavedChanges: false,
            attachedPageType: 'singleView',
            pageIcon: viewInfo.favicons[0]
        };
        await browser.updatePage({
            pageId: activePage.pageId,
            page: newActivePage
        });
    }
};

const updatePageToMultiViewPage = async (activePage: AttachedPageInternal) => {
    if (activePage.attachedPageType !== 'multiView') {
        const newTitle = await getCurrentSync().Browser.getUniquePageTitle();
        const browser = getCurrentSync().Browser.wrapSync(currentOFIdentity);
        browser.updatePage({
            pageId: activePage.pageId,
            page: {
                title: activePage.title ?? newTitle,
                singleViewName: null,
                attachedPageType: 'multiView'
            } as AttachedPageInternal
        });
    }
};

const getTabElements = (activePage: AttachedPageInternal) => {
    return Array.from(document.querySelectorAll(`[id="${activePage.layoutContainerKey}"] .lm_tab`));
};

export const showHideTabsBasedOnViewCount = (page: AttachedPageInternal, viewCount: number) => {
    const layoutContainer = document.getElementById(page.layoutContainerKey);
    if (!layoutContainer) {
        return;
    }
    if (viewCount > 1) {
        layoutContainer.setAttribute('data-single-view', 'false');
    } else {
        layoutContainer.setAttribute('data-single-view', 'true');
    }
};

const updatePageOptionsForViewCount = async (activePage: AttachedPageInternal | undefined) => {
    if (!activePage) {
        return;
    }
    const allTabs = getTabElements(activePage);
    if (allTabs.length > 1) {
        await updatePageToMultiViewPage(activePage);
    } else if (allTabs.length === 1) {
        await updatePageToHighLevelViewTab(activePage, getViewNameFromTabId(allTabs[0].id));
    }
};

export const debouncedUpdatePageOptionsForViewCount = debounce(updatePageOptionsForViewCount, 50, {
    leading: false,
    trailing: true
});

export const updatePageForViewCount = (activePage: AttachedPageInternal | undefined, immediate = false) => {
    try {
        if (!activePage || !activePage.layoutContainerKey) {
            return;
        }
        showHideTabsBasedOnViewCount(activePage, getTabElements(activePage).length);

        // update page options based on the number of tabs
        if (immediate) {
            updatePageOptionsForViewCount(activePage);
        } else {
            debouncedUpdatePageOptionsForViewCount(activePage);
        }
    } catch (e) {
        console.debug('UpdatePageForViewCount error:', e);
    }
};
