import type { AnyAction } from 'redux';
import type { ThunkDispatch } from 'redux-thunk';

import type { BrowserRootState } from '@enterprise/store';

let dispatchInstance: ThunkDispatch<unknown, unknown, AnyAction>;
let getStateInstance: () => BrowserRootState;

export const getState = () => {
    return getStateInstance();
};

export const dispatch: typeof dispatchInstance = (act: any) => {
    return dispatchInstance(act);
};

export const setGetStateInstance = (instance: typeof getStateInstance) => {
    getStateInstance = instance;
};

export const setDispatchInstance = (instance: typeof dispatchInstance) => {
    dispatchInstance = instance;
};
